#!/usr/bin/env node
// Post-install cleanup for macOS-specific pnpm/Next.js artifacts.
//
// macOS creates numbered copies ('file 2', 'dir 3'...) instead of overwriting
// when multiple processes write to the same paths. This causes two problems:
//
// 1. three-stdlib symlink: pnpm install in worktrees creates 'three-stdlib 2'...
//    while the canonical symlink disappears → tsc fails.
//
// 2. .next/ numbered artifacts: parallel builds leave 'server 2/', 'app 4/', etc.
//    causing ENOTEMPTY on the next build. Easiest fix: wipe .next/ entirely
//    (it is always regenerated by `next build` / `next dev`).

const fs = require('fs');
const path = require('path');
const { execSync } = require('child_process');
const root = path.resolve(__dirname, '..');

// ── 1. Restore canonical three-stdlib symlink ─────────────────────────────────
(function fixThreeStdlib() {
  const nodeModules = path.join(root, 'node_modules');
  const pnpmDir = path.join(nodeModules, '.pnpm');
  const linkPath = path.join(nodeModules, 'three-stdlib');

  let pnpmEntry;
  try {
    pnpmEntry = fs.readdirSync(pnpmDir).find((e) => e.startsWith('three-stdlib@'));
  } catch {
    return; // .pnpm dir absent (CI / non-pnpm install) — skip silently
  }
  if (!pnpmEntry) return;

  const target = path.join('.pnpm', pnpmEntry, 'node_modules', 'three-stdlib');

  try {
    const stat = fs.lstatSync(linkPath);
    if (stat.isSymbolicLink() && fs.readlinkSync(linkPath) === target) return; // already correct
    if (stat.isSymbolicLink()) fs.unlinkSync(linkPath);
  } catch {
    // Symlink doesn't exist — create it below
  }

  try {
    fs.symlinkSync(target, linkPath);
    console.log(`postinstall: restored three-stdlib → ${target}`);
  } catch (err) {
    console.warn(`postinstall: could not create three-stdlib symlink: ${err.message}`);
  }
})();

// ── 2. Wipe .next/ if it contains numbered-copy artifacts ────────────────────
// Numbered files/dirs (e.g. 'server 2', 'routes.d 3.ts') appear when multiple
// Next.js processes write to the same .next/ simultaneously. The build then
// fails with ENOTEMPTY when it tries to clean them. Since .next/ is always
// regenerated, the safest fix is to remove it when stale artifacts are present.
(function cleanNextDir() {
  const nextDir = path.join(root, '.next');
  if (!fs.existsSync(nextDir)) return;

  const hasNumberedArtifacts = (dir) => {
    let entries;
    try { entries = fs.readdirSync(dir); } catch { return false; }
    const numbered = /^.+ \d+(\..+)?$/;
    for (const entry of entries) {
      if (numbered.test(entry)) return true;
      const full = path.join(dir, entry);
      try {
        if (fs.statSync(full).isDirectory() && hasNumberedArtifacts(full)) return true;
      } catch { /* ignore */ }
    }
    return false;
  };

  if (!hasNumberedArtifacts(nextDir)) return;

  try {
    execSync(`rm -rf "${nextDir}"`, { stdio: 'ignore' });
    console.log('postinstall: cleared stale .next/ (numbered-copy artifacts detected)');
  } catch (err) {
    console.warn(`postinstall: could not clear .next/: ${err.message}`);
  }
})();
